// Normalise la reponse d'Ollama en champs stables.
// Supporte : structured outputs (format=schema), JSON brut, ou texte avec objet imbrique.
const data = $input.first().json;
const theme = $('Theme Picker').first().json.theme;

const raw = data.response ?? data.message?.content ?? '';
let parsed = null;

const tryParse = (s) => { try { return JSON.parse(s); } catch (_) { return null; } };

if (typeof raw === 'object' && raw !== null) parsed = raw;
else {
  parsed = tryParse(String(raw));
  if (!parsed) {
    const m = String(raw).match(/\{[\s\S]*\}/);
    if (m) parsed = tryParse(m[0]);
  }
}

const repair = (s) => {
  let t = String(s).trim();
  const lastKey = Math.max(t.lastIndexOf(':"'), t.lastIndexOf('",'), t.lastIndexOf(',"'));
  if (lastKey > 0) t = t.slice(0, lastKey + 1);
  t = t.replace(/"[^"]*$/s, '');
  let depth = 0;
  for (const ch of t) { if (ch === '{') depth++; else if (ch === '}') depth--; }
  return tryParse(t + '"' + '}'.repeat(Math.max(0, depth)));
};

// Si la generation a ete tronquee (done_reason=length), le JSON est
// invalide : on le repare plutot que de perdre la generation.
if (!parsed) parsed = repair(raw);

const field = (k) => {
  const v = parsed?.[k];
  return typeof v === 'string' ? v.trim() : '';
};

const hook = field('hook');
const body = field('body');
const call_to_action = field('call_to_action');

if (!hook && !body && !call_to_action) {
  throw new Error(
    'Reponse LLM inexploitable (modele=' + (data.model || 'n/a') +
    ', done_reason=' + (data.done_reason || 'n/a') +
    ', eval_count=' + (data.eval_count != null ? data.eval_count : 'n/a') +
    '). Brut: ' + String(raw).slice(0, 300)
  );
}

// Le message Telegram est envoye en parse_mode Markdown (legacy).
// Sans echappement, un simple "_" ou "*" produit par le modele fait
// echouer l'API Telegram en 400 "can't parse entities".
const md = (s) => String(s).replace(/([_*`[\]])/g, '\\$1');

// --- P0 : filtre de conformite editoriale (cf. WORKPLAN.md, section 2) ---
// Deux controles independants :
//   1. aucune premiere personne (je, mon, notre, ...) ;
//   2. aucun chiffre absent des donnees d'entree.
// Le prompt seul ne suffit pas sur un modele 3b : ce filtre est le garde-fou.
// Un echec met complete=false et alimente quality_flags ; le contenu reste
// visible pour correction, la publication automatique reste fermee.
const quality_flags = [];
const flag = (code, detail) => {
  const entry = code + (detail ? ' (' + detail + ')' : '');
  if (!quality_flags.includes(entry)) quality_flags.push(entry);
};

const FIRST_PERSON = [
  ['premiere personne', /(?:\bje\b|\bj['\u2019]|\bmoi\b)/i],
  ['possessif', /(?:\bmon\b|\bma\b|\bmes\b)/i]
];

// P2 : un champ manquant est signale comme les autres alertes. Sans cela le
// contenu incomplet partait avec un simple champ vide, sans aucun signal
// pour l'approbateur (alerte complete=false absente, cf. WORKPLAN.md P2).
for (const [k, v] of Object.entries({ hook, body, call_to_action })) {
  if (!v) flag('champ manquant', k);
}

// Chiffres autorises : ceux presents dans les donnees d'entree, donc le seul
// theme. Le theme n'en contient aucun -> tout chiffre libre est invente.
// Les chiffres INTEGRES a un mot (la marque BIZ4A, Odoo19) sont ignores :
// ils ne sont pas une donnee chiffree, mais un nom propre.
const allowed_numbers = new Set(
  (String(theme).match(/(?<![\p{L}\d])\d+(?:[.,]\d+)?(?![\p{L}])/gu) || []).map((n) => n.replace(',', '.'))
);

for (const [fieldName, value] of Object.entries({ hook, body, call_to_action })) {
  if (!value) continue;
  for (const [label, re] of FIRST_PERSON) {
    const m = value.match(re);
    if (m) flag(label, fieldName + ' : ' + m[0]);
  }
  for (const num of (value.match(/(?<![\p{L}\d])\d+(?:[.,]\d+)?(?![\p{L}])/gu) || [])) {
    if (!allowed_numbers.has(num.replace(',', '.'))) {
      flag('chiffre non source', fieldName + ' : ' + num);
    }
  }
}

return [{
  json: {
    theme,
    hook,
    body,
    call_to_action,
    // versions echappees, pretes pour Telegram
    hook_md: md(hook),
    body_md: md(body),
    cta_md: md(call_to_action),
    complete: !!(hook && body && call_to_action) && quality_flags.length === 0,
    // versions echappees des alertes, pretes pour Telegram
    quality_flags,
    quality_flags_md: quality_flags.map(md),
    model: data.model ?? 'llama3.2:3b',
    total_duration_ms: typeof data.total_duration === 'number' ? Math.round(data.total_duration / 1e6) : null,
    raw_preview: String(raw).slice(0, 300)
  }
}];

