// Bucle de regeneration (cf. WORKPLAN.md, P0) : garde le numero d'essai
// entre deux passages. .last() et non .first() pour relire l'iteration
// courante -- avec .first() la boucle ne progresserait jamais.
//
// theme est retransmis : le noeud LLM Request lit {{$json.theme}}, et
// le retour de boucle ne recoit que la sortie de ce compteur.
const prev = $('Compteur Tentative').last().json.attempt ?? 0;
const attempt = prev + 1;
if (attempt > 3) throw new Error('Bucle de regeneration non bornee.');
const theme = $('Theme Picker').first().json.theme;
return [{ json: { attempt, max_attempts: 3, theme } }];
